select count(*)
from test_design_task
where status = #{status}

select 
from test_design_task
where project_id = #{projectId}
  and idempotency_key = #{idempotencyKey}
limit 1

mapper.update:
update test_design_task
set status = #{nextStatus},
    error_message = null,
    updated_at = #{updatedAt}
where id = cast(#{id} as uuid)
  and status = #{expectedStatus}

with stale_tasks as (
    select id
    from test_design_task
    where status = 'RUNNING'
      and updated_at < #{staleBefore}
    order by updated_at asc
    limit #{limit}
)
update test_design_task
set status = 'FAILED',
    error_message = #{errorMessage},
    updated_at = #{failedAt}
where id in (select id from stale_tasks)
  and status = 'RUNNING'
  and updated_at < #{staleBefore}

mapper.insert:
insert into test_design_review_record (
    id, candidate_id, task_id, project_id, action, before_status, after_status, reviewer,
    comment, diff_json, created_at
) values (
    cast(#{id} as uuid), cast(#{candidateId} as uuid), cast(#{taskId} as uuid), #{projectId},
    #{action}, #{beforeStatus}, #{afterStatus}, #{reviewer}, #{comment}, cast(#{diffJson} as jsonb),
    #{createdAt}
)

insert into test_design_publish_record (
    id, task_id, candidate_id, project_id, requirement_id, asset_case_id, dry_run, action, result,
    error_message, published_by, created_at
) values (
    cast(#{id} as uuid), cast(#{taskId} as uuid), cast(#{candidateId} as uuid), #{projectId},
    cast(#{requirementId} as uuid), cast(#{assetCaseId} as uuid), #{dryRun}, #{action}, #{result},
    #{errorMessage}, #{publishedBy}, #{createdAt}
)
